/// Depth-first link identity.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(usize)]
pub enum Link {
    /// URDF link `trunk_base`.
    TrunkBase = 0,
    /// URDF link `yaw2roll`.
    Yaw2roll = 1,
    /// URDF link `hip_l`.
    HipL = 2,
    /// URDF link `upper_leg_left`.
    UpperLegLeft = 3,
    /// URDF link `leg`.
    Leg = 4,
    /// URDF link `ankle_l_v1`.
    AnkleLV1 = 5,
    /// URDF link `tire`.
    Tire = 6,
    /// URDF link `tire_2`.
    Tire2 = 7,
    /// URDF link `neck`.
    Neck = 8,
    /// URDF link `neck_pitch`.
    NeckPitch = 9,
    /// URDF link `yaw_roll_motion`.
    YawRollMotion = 10,
    /// URDF link `jaw_soft`.
    JawSoft = 11,
    /// URDF link `bearing_roll`.
    BearingRoll = 12,
    /// URDF link `hip_l_2`.
    HipL2 = 13,
    /// URDF link `upper_leg_right`.
    UpperLegRight = 14,
    /// URDF link `leg_2`.
    Leg2 = 15,
    /// URDF link `ankle_r_v1`.
    AnkleRV1 = 16,
    /// URDF link `tire_3`.
    Tire3 = 17,
    /// URDF link `tire_4`.
    Tire4 = 18,
}

